// Deterministic stampede simulation — no randomness, no timers.
// 1000 readers hit one hot key in a 200ms window; rebuild takes 120ms.
// Three configs to model (do not change the flags):
const configs = {
  // A: naive lock, EX shorter than rebuild -> herd leaks through on expiry
  A: { lockExMs: 50, rebuildMs: 120, singleFlight: true, serveStale: false },
  // B: lock EX longer than rebuild + single-flight -> exactly one
  B: { lockExMs: 300, rebuildMs: 120, singleFlight: true, serveStale: false },
  // C: SWR + single-flight (serve stale, one background refresh) -> exactly one
  C: { lockExMs: 50, rebuildMs: 120, singleFlight: true, serveStale: true }
};

